INSERT INTO mcp_tool (id, name, display_name, description, domain, priority, cost_level, avg_latency_ms, enabled, handler_bean, source, http_method, path_template, operation_id, http_path, service_id, input_schema, embedding) VALUES ('d3eedbf8-89e8-4fc9-9fec-727d9cd32aef', 'DateWindowFacadeTool', 'Date Window', 'Resolve a relative date range ("last month", "in the last six months", "this quarter", "over the last twelve months compared with the same twelve months last year") to concrete calendar dates. Call this before any other tool argument that takes a date or a date range, then copy its startDate/endDate into that tool''s arguments verbatim and quote its statement in the answer.', 'date-window', 1, 'low', 5, true, 'dateWindowFacadeTool', 'facade', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO mcp_tool (id, name, display_name, description, domain, priority, cost_level, avg_latency_ms, enabled, handler_bean, source, http_method, path_template, operation_id, http_path, service_id, input_schema, embedding) VALUES ('d64f2bc8-1a5a-4150-bbf3-c15203a1b64f', 'InvoiceFacadeTool', 'Invoice', 'Invoice lookup, invoice search, a customer''s distinct invoices, per-customer revenue for a reporting period (top customers by revenue, invoice count, average invoice value, and most recent invoice date), and the average number of days from workorder creation to invoice creation for one date window (loop once per period for a by-month trend).', 'invoice', 0.9, 'medium', 250, true, 'invoiceFacadeTool', 'facade', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO mcp_tool (id, name, display_name, description, domain, priority, cost_level, avg_latency_ms, enabled, handler_bean, source, http_method, path_template, operation_id, http_path, service_id, input_schema, embedding) VALUES ('90444c65-0f6b-42c2-987a-427e09486946', 'GlossaryFacadeTool', 'Business Glossary', 'Look up the agreed business definition of an analytical phrase ("best customers", "payment problems", "running low", "backed up in the shop", "most productive technicians"). Call before answering any question whose metric is a business term rather than a plain field: returns the agreed metric and default window to apply, or reports that the metric has no agreed definition and must be clarified with the user.', 'glossary', 1, 'low', 5, true, 'glossaryFacadeTool', 'facade', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
